const assert=require('node:assert/strict'),fs=require('node:fs');const h=fs.readFileSync('paper-workspace.html','utf8'),j=fs.readFileSync('paper-cabinet.js','utf8'),w=fs.readFileSync('paper-workspace.js','utf8'),c=fs.readFileSync('paper-design.css','utf8');const ids=[...h.matchAll(/\bid="([^"]+)"/g)].map(m=>m[1]);assert.equal(new Set(ids).size,ids.length,'Unique HTML IDs');for(const source of [j,w])for(const m of source.matchAll(/\$\('([^']+)'\)/g))assert(ids.includes(m[1]),'Missing element '+m[1]);for(const id of ['paperCreateDialog','paperCopyDialog','questionDialog'])assert(h.includes('<dialog id="'+id+'"'));for(const marker of ['paperSubjectFilter','paperStatusFilter','copyChoices','paperTotal','paperEditor','paperCamera','printArea'])assert(ids.includes(marker));assert(c.includes('@media screen'));assert(c.includes('@media print'));assert(j.includes("paper/copy.php"));assert(j.includes("paper/create.php"));assert(j.includes("questions/update.php"));console.log('PAPER design and event wiring OK');
for(const id of ['paperPreview','navPreview','previewPrint','reviewTotal','reviewFilled','reviewUncertain','reviewManual','reviewFilter','reviewPhotoEmpty'])assert(ids.includes(id),'missing workspace view element '+id);assert(h.includes('data-paper-view="paperLibrary"'));assert(h.includes('<section class="workspace no-print camera-panel" id="paperCamera">'));assert(c.includes('data-paper-view="review"'));assert(c.includes('#printArea[hidden]'));assert(j.includes('document.body.dataset.paperView=id'));assert(w.includes('function reviewStats()'));assert(w.includes("option.text,'paper-review-option-text'"));assert(w.includes("detail:'paperPreview'"));console.log('PAPER independent views and review UI wiring OK');

